  async function afterRender(){if(state.screen==='setup'&&!permissionUI.inspected){permissionUI.inspected=true;inspectPermissions()}if(state.screen==='scanner')startScanner();if(state.screen==='radar')startRadar();if(state.screen==='camera')startCamera();if(state.screen==='riddle')startRiddleTimer();if(state.screen==='photoWait'||state.screen==='questionWait')startCountdown();if(state.screen==='celebration')sound('final')}
