  async function inspectPermissions(){permissionUI.checking=true;render();if(!window.isSecureContext){permissionUI.camera='unavailable';permissionUI.gps='unavailable';permissionUI.cameraMessage='La càmera requereix una connexió segura HTTPS.';permissionUI.gpsMessage='La ubicació requereix una connexió segura HTTPS.'}else{const[cameraState,gpsState]=await Promise.all([queryPermissionState('camera'),queryPermissionState('geolocation')]);if(cameraState==='granted')permissionUI.camera='prepared';else if(cameraState==='denied')permissionUI.camera='blocked';else if(permissionUI.camera!=='prepared'&&permissionUI.camera!=='denied')permissionUI.camera=navigator.mediaDevices?.getUserMedia?'pending':'unavailable';if(gpsState==='granted')permissionUI.gps='prepared';else if(gpsState==='denied')permissionUI.gps='blocked';else if(permissionUI.gps!=='prepared'&&permissionUI.gps!=='denied')permissionUI.gps='geolocation'in navigator?'pending':'unavailable'}if(!('DeviceOrientationEvent'in window))permissionUI.orientation='unavailable';else if(typeof DeviceOrientationEvent.requestPermission!=='function'&&permissionUI.orientation!=='prepared'){const received=await waitForOrientationData(1500);permissionUI.orientation=received?'prepared':'pending';if(received)permissionUI.orientationMessage='S’han detectat dades reals d’orientació.'}permissionUI.sound=audioCtx?'prepared':'pending';permissionUI.vibration='vibrate'in navigator?'prepared':'unavailable';permissionUI.checking=false;syncPermissionState();render()}
  async function requestCameraPermission(){if(!window.isSecureContext){permissionUI.camera='unavailable';permissionUI.cameraMessage='RadarQuest necessita una connexió segura HTTPS per utilitzar la càmera.';syncPermissionState();render();return}permissionUI.checking=true;permissionUI.cameraMessage='Sol·licitant accés a la càmera…';render();try{const checkStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});checkStream.getTracks().forEach(track=>track.stop());permissionUI.camera='prepared';permissionUI.cameraMessage='La càmera s’ha comprovat i s’ha tancat correctament.'}catch(error){const p=await queryPermissionState('camera');permissionUI.camera=p==='denied'?'blocked':error?.name==='NotAllowedError'?'denied':'unavailable';permissionUI.cameraMessage=permissionUI.camera==='unavailable'?'No s’ha pogut accedir a cap càmera compatible.':'Cal activar el permís de càmera del navegador per poder continuar.'}permissionUI.checking=false;syncPermissionState();render()}
  async function requestGPSPermission(){if(!window.isSecureContext){permissionUI.gps='unavailable';permissionUI.gpsMessage='RadarQuest necessita una connexió segura HTTPS per utilitzar el GPS.';syncPermissionState();render();return}if(!navigator.geolocation){permissionUI.gps='unavailable';permissionUI.gpsMessage='Aquest dispositiu no ofereix geolocalització compatible.';syncPermissionState();render();return}permissionUI.checking=true;permissionUI.gpsMessage='Sol·licitant accés a la ubicació…';render();try{const pos=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:15000,maximumAge:0}));permissionUI.gps='prepared';permissionUI.gpsAccuracy=pos.coords.accuracy;permissionUI.gpsMessage=`Precisió aproximada: ±${Math.round(pos.coords.accuracy)} m`}catch(error){const p=await queryPermissionState('geolocation');permissionUI.gps=p==='denied'?'blocked':error?.code===1?'denied':'unavailable';permissionUI.gpsMessage=error?.code===1?'Cal activar el permís d’ubicació del navegador per poder continuar.':error?.code===3?'No s’ha pogut obtenir la ubicació a temps. Proveu-ho en un espai obert.':'No s’ha pogut obtenir la ubicació del dispositiu.'}permissionUI.checking=false;syncPermissionState();render()}
