  function fittedSize(width,height,maxWidth=600,maxHeight=800){const scale=Math.min(maxWidth/width,maxHeight/height,1);return{width:Math.max(1,Math.round(width*scale)),height:Math.max(1,Math.round(height*scale))}}
  function capturePhoto(){const video=document.getElementById('video');if(!video||!video.videoWidth){signalError('system');return}const size=fittedSize(video.videoWidth,video.videoHeight);canvas.width=size.width;canvas.height=size.height;const c=canvas.getContext('2d');if(!nativeCameraZoom&&cameraZoom>1){const sw=video.videoWidth/cameraZoom,sh=video.videoHeight/cameraZoom,sx=(video.videoWidth-sw)/2,sy=(video.videoHeight-sh)/2;c.drawImage(video,sx,sy,sw,sh,0,0,size.width,size.height)}else c.drawImage(video,0,0,size.width,size.height);captureURL=canvas.toDataURL('image/jpeg',.88);stopMedia();setState({screen:'preview'})}
  async function validatePhoto(){if(!captureURL)return;app.querySelector('[data-action="usePhoto"]')?.setAttribute('disabled','');try{const score=await compareImages(captureURL,activeTest().referenceImage);captureURL=null;if(score>=CONFIG.PHOTO_SIMILARITY_THRESHOLD){sound('photoOk');vibrate([100,80,100,80,400]);setState({screen:'photoCorrect',photoMessage:'',questionLevel:0,questionAttempts:0,photoFailures:state.photoFailures})}else{signalError('incorrect');const failures=state.photoFailures+1,remaining=CONFIG.PHOTO_INITIAL_ATTEMPTS-failures,message=`No coincideix prou amb l’element de referència. Torneu-ho a intentar.${remaining>0?` Queden ${remaining} intents abans de la pista.`:''}`;if(failures>=CONFIG.PHOTO_INITIAL_ATTEMPTS){setState({screen:'photoWait',photoFailures:failures,photoMessage:message,waitEnd:Date.now()+CONFIG.PHOTO_HELP_WAIT_SECONDS*1000,phaseAfterWait:'photoHelp'})}else setState({screen:'camera',photoFailures:failures,photoMessage:message})}}catch{signalError('system');captureURL=null;setState({screen:'camera',photoMessage:'No hem pogut processar la fotografia. Torneu-la a fer.'})}}
  function loadImage(src){return new Promise((res,rej)=>{const i=new Image();i.onload=()=>res(i);i.onerror=rej;i.src=src})}
  function resizeForComparison(img){const size=fittedSize(img.width,img.height),cv=document.createElement('canvas');cv.width=size.width;cv.height=size.height;const c=cv.getContext('2d',{alpha:false});c.imageSmoothingEnabled=true;c.imageSmoothingQuality='high';c.drawImage(img,0,0,size.width,size.height);return cv}
