  function extractFeatures(img,crop,offsetX=0,offsetY=0,rotation=0){const size=72,cv=document.createElement('canvas');cv.width=cv.height=size;const c=cv.getContext('2d',{willReadFrequently:true});c.fillStyle='#777';c.fillRect(0,0,size,size);const sw=img.width*crop,sh=img.height*crop,maxX=Math.max(0,(img.width-sw)/2),maxY=Math.max(0,(img.height-sh)/2),sx=Math.max(0,Math.min(img.width-sw,(img.width-sw)/2+offsetX*maxX)),sy=Math.max(0,Math.min(img.height-sh,(img.height-sh)/2+offsetY*maxY));c.save();c.translate(size/2,size/2);c.rotate(rotation);c.drawImage(img,sx,sy,sw,sh,-size/2,-size/2,size,size);c.restore();const d=c.getImageData(0,0,size,size).data,gray=new Float32Array(size*size),color=new Float32Array(36),edge=new Float32Array(9*8),globalEdge=new Float32Array(8);let mean=0;for(let i=0,p=0;i<d.length;i+=4,p++){const r=d[i]/255,g=d[i+1]/255,b=d[i+2]/255;gray[p]=.299*r+.587*g+.114*b;mean+=gray[p];const max=Math.max(r,g,b),min=Math.min(r,g,b),delta=max-min;let h=0;if(delta){if(max===r)h=((g-b)/delta+6)%6;else if(max===g)h=(b-r)/delta+2;else h=(r-g)/delta+4}const sat=max?delta/max:0;color[Math.min(11,Math.floor(h*2))]++;color[12+Math.min(11,Math.floor(sat*12))]++;color[24+Math.min(11,Math.floor(max*12))]++}mean/=gray.length;let variance=0;for(let i=0;i<gray.length;i++)variance+=(gray[i]-mean)**2;const contrast=Math.sqrt(variance/gray.length);for(let i=0;i<gray.length;i++)gray[i]=(gray[i]-mean)/(contrast||1);let edgeCount=0;for(let y=1;y<size-1;y++)for(let x=1;x<size-1;x++){const p=y*size+x,gx=gray[p+1]-gray[p-1],gy=gray[p+size]-gray[p-size],mag=Math.hypot(gx,gy);if(mag>.18){edgeCount++;const ang=(Math.atan2(gy,gx)+Math.PI)%Math.PI,bin=Math.min(7,Math.floor(ang/Math.PI*8)),cell=Math.min(8,Math.floor(y/(size/3))*3+Math.floor(x/(size/3)));edge[cell*8+bin]+=mag;globalEdge[bin]+=mag}}normalize(color);normalize(edge);normalize(globalEdge);return{gray,color,edge,globalEdge,contrast,edgeDensity:edgeCount/(size*size)}}
  function normalize(v){let n=0;for(const x of v)n+=x*x;n=Math.sqrt(n)||1;for(let i=0;i<v.length;i++)v[i]/=n}
