  function registerActiveTest(){const test=activeTest(),enigma=activeRiddle();if(!test||!enigma||state.completedRiddles.includes(enigma.id))return false;state.completedTests=[...new Set([...state.completedTests,test.id])];state.completedRiddles=[...state.completedRiddles,enigma.id];state.questionAttempts=0;state.questionDeadline=null;state.waitEnd=null;state.phaseAfterWait=null;save();return true}
  function completeActiveTest(){if(!registerActiveTest())return;sound('victory');vibrate([100,80,100,80,400]);setState({screen:'completed',questionNotice:''})}
  function completeWithSolution(notice){if(!registerActiveTest())return;setState({screen:'solution',questionNotice:notice})}
  function advanceRiddle(reason){signalError('incorrect');if(state.questionLevel<2){const nextLevel=state.questionLevel+1;setState({screen:'riddle',questionLevel:nextLevel,questionAttempts:0,questionDeadline:Date.now()+CONFIG.QUESTION_HELP_WAIT_SECONDS*1000,questionNotice:`${reason} S'ha desbloquejat l'ajuda ${nextLevel}.`})}else completeWithSolution(`${reason} Es mostra la solució.`)}
  function checkAnswer(){const input=document.getElementById('answer'),msg=document.getElementById('answerMessage');const text=normalizeText(input?.value||'');if(!text){signalError('incorrect');msg.innerHTML='<div class="toast error">Escriviu una resposta abans de validar-la.</div>';return}if(answerIsAcceptable(activeRiddle(),text)){sound('answerOk');completeActiveTest()}else{signalError('incorrect');const attempts=state.questionAttempts+1;if(attempts<CONFIG.QUESTION_ATTEMPTS_PER_LEVEL){setState({questionAttempts:attempts},false);msg.innerHTML=`<div class="toast error"><strong>ERROR</strong><br>La resposta no és correcta. Torneu-ho a intentar.</div>`;app.querySelector('.attempt').textContent=`Intent ${attempts+1} de ${CONFIG.QUESTION_ATTEMPTS_PER_LEVEL}`;input.value=''}else if(state.questionLevel<2){const nextLevel=state.questionLevel+1;setState({screen:'riddle',questionLevel:nextLevel,questionAttempts:0,questionDeadline:Date.now()+CONFIG.QUESTION_HELP_WAIT_SECONDS*1000,questionNotice:`Massa intents incorrectes. S'ha desbloquejat l'ajuda ${nextLevel}.`})}else completeWithSolution('S’han esgotat els intents. Es mostra la solució.')}}
  function startRiddleTimer(){if(!Number.isFinite(state.questionDeadline)){state.questionDeadline=Date.now()+CONFIG.QUESTION_HELP_WAIT_SECONDS*1000;save()}const tick=()=>{const left=Math.max(0,Math.ceil((state.questionDeadline-Date.now())/1000)),el=document.getElementById('riddleCountdown');if(el)el.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;if(left<=0){clearInterval(countdownTimer);countdownTimer=null;advanceRiddle('Temps esgotat.')}};tick();if(state.screen==='riddle')countdownTimer=setInterval(tick,250)}
  function startCountdown(){const tick=()=>{const left=Math.max(0,Math.ceil(((state.waitEnd||Date.now())-Date.now())/1000)),el=document.getElementById('countdown');if(el)el.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;if(left<=0){clearInterval(countdownTimer);countdownTimer=null;if(state.phaseAfterWait==='photoHelp')setState({screen:'photoHelp',waitEnd:null});else if(state.phaseAfterWait==='solution')completeActiveTest();else setState({screen:'riddle',waitEnd:null})}};tick();countdownTimer=setInterval(tick,250)}
  async function runLocalSelfTest(){const simulacions=[];for(let group=1;group<=CONFIG.GROUPS_TOTAL;group++){const completed=[];while(completed.length<CONFIG.MISSIONS_PER_GROUP){const id=chooseUnusedRiddleId(completed);if(!id)break;completed.push(id)}simulacions.push({group,completed,unique:new Set(completed).size===CONFIG.MISSIONS_PER_GROUP})}document.documentElement.dataset.radarquestTest=JSON.stringify({enigmes:ENIGMES.length,proves:PROVES.length,grups:simulacions.length,nouPerGrup:simulacions.every(s=>s.unique),associacions:PROVES.map(p=>({id:p.id,coordenades:p.coordenades,imatge:p.referenceImage}))})}
  try{validateConfig();render();if(location.hostname==='127.0.0.1'||location.hostname==='localhost')runLocalSelfTest().catch(console.error)}catch(e){console.error(e);state={...initialState(),screen:'error',errorMessage:'La configuració interna del joc conté dades duplicades. Aviseu la persona responsable.'};render()}
  
